    <style>
        :root{--ink:#17201b;--muted:#68736c;--line:#e3e8e3;--paper:#f8faf8;--white:#fff;--red:#bd1712;--deep:#241b18;--olive:#dfe9df}*{box-sizing:border-box}body{margin:0;background:var(--paper);color:var(--ink);font-family:Manrope,Arial,sans-serif;-webkit-font-smoothing:antialiased}.about-nav{height:76px;border-bottom:1px solid var(--line);background:rgba(255,255,255,.88);backdrop-filter:blur(12px)}.about-nav-in,.about-wrap{max-width:1160px;margin:auto;padding:0 28px}.about-nav-in{height:100%;display:flex;align-items:center;justify-content:space-between}.brand{color:var(--red);font-size:18px;font-weight:800;letter-spacing:-.04em;text-decoration:none}.nav-back{color:#536058;font-size:13px;font-weight:700;text-decoration:none}.nav-back:hover{color:var(--red)}.about-hero{padding:88px 0 78px;background:linear-gradient(135deg,#f8faf8 0%,#f8faf8 58%,#f1f5f1 100%)}.hero-grid{display:grid;grid-template-columns:minmax(0,1.1fr) 420px;gap:80px;align-items:center}.eyebrow{margin:0 0 19px;color:var(--red);font:500 11px 'DM Mono',monospace;letter-spacing:.12em;text-transform:uppercase}.hero-title{max-width:700px;margin:0;font-size:clamp(42px,5.2vw,68px);line-height:1.04;letter-spacing:-.065em}.hero-title em{color:var(--red);font-style:normal}.hero-copy{max-width:640px;margin:26px 0 0;color:#58645c;font-size:16px;line-height:1.78}.hero-copy+p{margin-top:13px}.hero-actions{display:flex;gap:11px;margin-top:31px}.button{display:inline-flex;align-items:center;gap:9px;padding:13px 18px;border:1px solid var(--red);background:var(--red);color:#fff;font-size:13px;font-weight:800;text-decoration:none;transition:.18s}.button:hover{background:#99110c}.button-alt{border-color:#cfd7d0;background:#fff;color:#28342c}.button-alt:hover{border-color:#9ca99f;background:#f4f7f4}.about-panel{overflow:hidden;border:1px solid #d9e2da;background:var(--white);box-shadow:0 18px 40px rgba(29,54,35,.08)}.panel-top{padding:30px;background:var(--deep);color:white}.pin{display:grid;width:40px;height:40px;place-items:center;border:1px solid rgba(255,255,255,.25);color:#ffc9c6;font-size:20px}.panel-label{margin:22px 0 6px;color:#cbbdb6;font:500 10px 'DM Mono',monospace;letter-spacing:.1em;text-transform:uppercase}.panel-city{margin:0;font-size:25px;line-height:1.15;letter-spacing:-.045em}.panel-sub{margin:7px 0 0;color:#d9d0cb;font-size:13px}.panel-list{margin:0;padding:0;list-style:none}.panel-list li{display:flex;gap:13px;padding:18px 22px;border-top:1px solid #e8ede8}.panel-dot{display:grid;width:25px;height:25px;flex:0 0 25px;place-items:center;background:#f9e7e5;color:var(--red);font-size:12px;font-weight:800}.panel-list strong{display:block;font-size:13px}.panel-list span{display:block;margin-top:3px;color:#758078;font-size:11px;line-height:1.45}.tech-section{padding:78px 0;background:#fff;border-top:1px solid var(--line)}.section-head{display:grid;grid-template-columns:1fr 1fr;gap:60px;align-items:end;margin-bottom:33px}.section-title{margin:0;font-size:34px;line-height:1.12;letter-spacing:-.055em}.section-intro{margin:0;color:var(--muted);font-size:14px;line-height:1.7}.tech-grid{display:grid;grid-template-columns:repeat(3,1fr);border-top:1px solid var(--line);border-left:1px solid var(--line)}.tech{min-height:175px;padding:25px;border-right:1px solid var(--line);border-bottom:1px solid var(--line);background:#fff}.tech:hover{background:#fbfdfb}.tech-num{color:var(--red);font:500 10px 'DM Mono',monospace;letter-spacing:.08em}.tech h3{margin:28px 0 8px;font-size:18px;letter-spacing:-.04em}.tech p{margin:0;color:var(--muted);font-size:12px;line-height:1.6}.closing{padding:78px 0;text-align:center}.closing-box{max-width:760px;margin:auto}.closing h2{margin:0;font-size:clamp(30px,4vw,46px);letter-spacing:-.06em;line-height:1.12}.closing p{max-width:570px;margin:17px auto 27px;color:var(--muted);font-size:14px;line-height:1.7}.about-footer{padding:26px 0;border-top:1px solid var(--line);background:#fff}.footer-in{display:flex;justify-content:space-between;gap:16px;color:#7c867f;font:400 10px 'DM Mono',monospace}@media(max-width:800px){.about-hero{padding:62px 0}.hero-grid,.section-head{grid-template-columns:1fr;gap:38px}.about-panel{max-width:500px}.tech-grid{grid-template-columns:repeat(2,1fr)}.section-head{margin-bottom:27px}}@media(max-width:520px){.about-nav-in,.about-wrap{padding:0 20px}.about-hero,.tech-section,.closing{padding:52px 0}.nav-back{font-size:12px}.hero-title{font-size:40px}.hero-actions{flex-direction:column;align-items:flex-start}.button{justify-content:center;width:100%}.tech-grid{grid-template-columns:1fr}.tech{min-height:145px}.footer-in{flex-direction:column}.section-title{font-size:30px}}
