        .nav-back{font-size:14px}.eyebrow{font-size:12px}.panel-label{font-size:11px}.panel-sub{font-size:14px}.panel-list strong{font-size:14px}.panel-list span{font-size:12px}.section-intro{font-size:15px}.tech-num{font-size:11px}.tech p{font-size:13px}.closing p{font-size:15px}.footer-in{font-size:11px}
        @media(max-width:520px){.nav-back{font-size:13px}}
